ALTER TABLE quiz_questions ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE quizzes ALTER COLUMN id SET DEFAULT gen_random_uuid();

BEGIN;
DELETE FROM quiz_questions WHERE quiz_id IN (SELECT id FROM quizzes WHERE course_id='499b113c-2644-4125-8042-de8dfe1416e6' AND quiz_sequence=1);
DELETE FROM quizzes WHERE course_id='499b113c-2644-4125-8042-de8dfe1416e6' AND quiz_sequence=1;
VALUES (gen_random_uuid(), '499b113c-2644-4125-8042-de8dfe1416e6', 'Module 1 Assessment', 'Twenty questions on the fundamentals of Bead & Jewelry Making.', 70, 30, 'module', 'beginner', 1);
COMMIT;

SELECT COUNT(*) AS questions_loaded FROM quiz_questions
WHERE quiz_id = (SELECT id FROM quizzes WHERE course_id='499b113c-2644-4125-8042-de8dfe1416e6' AND quiz_sequence=1);
-- expect 20
